/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` FUNCTION `get_object_segment_id`(p_object_id INT,


    p_object_type_name VARCHAR(128)


) RETURNS int(11)
    READS SQL DATA
    DETERMINISTIC
BEGIN


    DECLARE v_segment_id INT;


    DECLARE v_object_type_id INT;


    


    -- Get Object_Type_ID


    SELECT ID INTO v_object_type_id


    FROM segment_object_type


    WHERE Type = p_object_type_name


    LIMIT 1;


    


    IF v_object_type_id IS NULL THEN


        RETURN 1; -- Default to Enterprise


    END IF;


    


    -- Get segment ID from segment_x_resource


    SELECT sxr.Segment_ID INTO v_segment_id


    FROM segment_x_resource sxr


    JOIN object_reference orr ON sxr.Object_Reference_ID = orr.ID


    WHERE orr.Object_ID = p_object_id


      AND orr.Object_Type_ID = v_object_type_id


      AND sxr.Deleted_At IS NULL


    LIMIT 1;


    


    -- Return segment ID or 1 (Enterprise) as default


    RETURN COALESCE(v_segment_id, 1);


END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `assign_object_to_segment` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `assign_object_to_segment`(


    IN p_object_id INT,


    IN p_object_type_name VARCHAR(128),


    IN p_segment_id INT,


    IN p_user_id INT


)
BEGIN


    DECLARE v_object_ref_id INT;


    


    -- Get or create object reference


    CALL get_or_create_object_ref(p_object_id, p_object_type_name, v_object_ref_id);


    


    -- Soft delete existing assignment (if any)


    UPDATE segment_x_resource


    SET Deleted_At = NOW(),


        Last_UpdatedBy = p_user_id,


        Last_Updated_At = NOW()


    WHERE Object_Reference_ID = v_object_ref_id


      AND Deleted_At IS NULL;


    


    -- Create new assignment


    INSERT INTO segment_x_resource (


        Segment_ID,


        Object_Reference_ID,


        Created_By,


        Created_At,


        Last_UpdatedBy,


        Last_Updated_At


    ) VALUES (


        p_segment_id,


        v_object_ref_id,


        p_user_id,


        NOW(),


        p_user_id,


        NOW()


    );


END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ZERO_IN_DATE,NO_ZERO_DATE,NO_ENGINE_SUBSTITUTION' */ ;
/*!50003 DROP PROCEDURE IF EXISTS `get_or_create_object_ref` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_unicode_ci */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `get_or_create_object_ref`(


    IN p_object_id INT,


    IN p_object_type_name VARCHAR(128),


    OUT p_object_ref_id INT


)
BEGIN


    DECLARE v_object_type_id INT;


    


    -- Get Object_Type_ID from segment_object_type table


    SELECT ID INTO v_object_type_id


    FROM segment_object_type


    WHERE Type = p_object_type_name


    LIMIT 1;


    


    -- If object type doesn't exist, create it


    IF v_object_type_id IS NULL THEN


        INSERT INTO segment_object_type (Type, Created_At, Last_Updated_At)


        VALUES (p_object_type_name, NOW(), NOW());


        SET v_object_type_id = LAST_INSERT_ID();


    END IF;


    


    -- Check if object_reference exists


    SELECT ID INTO p_object_ref_id


    FROM object_reference


    WHERE Object_ID = p_object_id


      AND Object_Type_ID = v_object_type_id


    LIMIT 1;


    


    -- If not exists, create it


    IF p_object_ref_id IS NULL THEN


        INSERT INTO object_reference (Object_ID, Object_Type_ID, Created_At, Last_Updated_At)


        VALUES (p_object_id, v_object_type_id, NOW(), NOW());


        


        SET p_object_ref_id = LAST_INSERT_ID();


    END IF;


END ;;
DELIMITER ;
